import React from "react";
import Slider from "react-slick";

export default function Hero() {
  const settings = {
    dots: true,
    infinite: true,
    speed: 200, // Faster transition speed
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 2000, // Faster sliding interval
  };

  const slides = [
    { src: "/welcomingPoster.png", alt: "Image 1" },
    { src: "/poster1.png", alt: "Image 2" },
    { src: "/poster2.png", alt: "Image 3" },
  ];

  return (
    <section className="relative py-6 md:py-10 h-[300px] md:h-[400px] overflow-hidden">
      <Slider {...settings}>
        {slides.map((slide, index) => (
          <div key={index} className="relative h-[300px] md:h-[400px]">
            <img
              src={slide.src}
              alt={slide.alt}
              className="w-full h-full object-contain" // Prevents image zooming
            />
          </div>
        ))}
      </Slider>
    </section>
  );
}
